{
  "status": "SUPPORTED",
  "task_summary": "Place two refreshment containers on surfaces near seating, and move one entertainment control to a central accessible surface.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_container",
        "entity_kind": "OBJECT",
        "function": "Holds or contains a drink or snack for a person.",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["cup", "glass", "bowl", "plate"],
        "required_properties": ["holds_refreshment"]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Device used to operate the television.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["remote", "switch", "button"],
        "required_properties": ["controls_tv"]
      },
      {
        "id": "surface_near_seating",
        "entity_kind": "REGION",
        "function": "Flat area near a chair for placing personal items.",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["side_table", "armchair_armrest", "floor"],
        "required_properties": ["flat", "near_chair"]
      },
      {
        "id": "shared_accessible_surface",
        "entity_kind": "REGION",
        "function": "Central area reachable by multiple people.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["coffee_table", "console_table", "desk"],
        "required_properties": ["central", "reachable_by_both"]
      }
    ],
    "functional_relations": [
      {
        "id": "refreshment_placement",
        "relation": "refreshment_container is placed on surface_near_seating",
        "participant_roles": ["refreshment_container", "surface_near_seating"]
      ,
        "required": true
      },
      {
        "id": "control_placement",
        "relation": "entertainment_control is placed on shared_accessible_surface",
        "participant_roles": ["entertainment_control", "shared_accessible_surface"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "place_refreshments",
        "operation": "Place refreshment_container on surface_near_seating",
        "participant_roles": ["refreshment_container", "surface_near_seating"],
        "operation_count": 2
      },
      {
        "id": "move_control",
        "operation": "Place entertainment_control on shared_accessible_surface",
        "participant_roles": ["entertainment_control", "shared_accessible_surface"],
        "operation_count": 1
      }
    ]
  },
