      ],
      "entertainment_control": [
        {"label": "black remote on foreground desk", "visual_description": "black rectangular object with buttons on the wooden desk"}
      ],
      "surface_near_seating": [
        {"label": "left side table", "visual_description": "light wood side table next to the left armchair"},
        {"label": "right side table", "visual_description": "light wood side table next to the right armchair"}
      ],
